def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    counts = Counter(x for row in grid for x in row)
    common = [c for c, _ in counts.most_common(2)]
    fill = common[0]

    # Marker rows contain colors other than the two dominant grid colors.
    marker_rows = [
        r for r in range(h)
        if any(grid[r][c] not in common for c in range(w))
    ]
    marker_cols = sorted({
        c for r in marker_rows for c in range(w)
        if grid[r][c] not in common
    })

    if len(marker_rows) < 2 or len(marker_cols) < 2:
        return [[fill]]

    out = []
    for r in range(len(marker_rows) - 1):
        row = []
        for c in range(len(marker_cols) - 1):
            vals = (
                grid[marker_rows[r]][marker_cols[c]],
                grid[marker_rows[r]][marker_cols[c + 1]],
                grid[marker_rows[r + 1]][marker_cols[c]],
                grid[marker_rows[r + 1]][marker_cols[c + 1]],
            )
            row.append(vals[0] if vals.count(vals[0]) == 4 else fill)
        out.append(row)
    return out
